code.source:
#include <iostream>
using namespace std;

class Counter {
    int count_ = 0;

public:
    void increment() { count_++; }
    int get() const { return count_; }
};

int main() {
    Counter c;
    c.increment();
    c.increment();
    cout << c.get() << endl;
    return 0;
}

